const vip = '${VIP_SENDERS}'.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const rescue = /int[ée]rim|mission|aide[- ]soignant|\bASH\b|FFAS|alternance|TSSR|\bCDD\b|candidature|entretien|recrut/i;
return $input.all().map(({ json: m }) => {
  const from = m.from?.text || m.from || '';
  const subject = m.subject || '';
  const addr = (from.match(/<([^>]+)>/)?.[1] || from).toLowerCase();
  const text = (m.textPlain || m.text || '').replace(/\s+/g, ' ').slice(0, 1500);
  const h = m.metadata || m.headers || {}; // the IMAP node puts the raw headers under `metadata`
  const bulk = 'list-unsubscribe' in h || /bulk|list|junk/i.test(h.precedence || '');
  const isVip = vip.some(v => addr === v || addr.endsWith('@' + v) || addr.endsWith('.' + v));
  if (isVip) return { json: { from, subject, route: 'vip', msg: `📬 ${subject}\nDe : ${from}\n→ expéditeur prioritaire` } };
  if (bulk && !rescue.test(subject + ' ' + text)) return { json: { from, subject, route: 'bruit', kind: 'newsletter' } };
  return { json: { from, subject, route: 'ia', body: {
    model: 'openai/gpt-oss-120b',
    reasoning_effort: 'low',
    temperature: 0,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: "Tu tries les mails de Kram, qui cherche : une alternance TSSR (syst\u00e8mes/r\u00e9seaux, Toulouse), des missions d'int\u00e9rim aide-soignant (FFAS/ASH), et des clients pour son activit\u00e9 de prestataire informatique.\n\nIMPORTANT = exige une action ou une r\u00e9ponse de sa part : recruteurs, entreprises, \u00e9coles ou organismes de formation, agences d'int\u00e9rim, clients ou prospects, plateformes freelance (Malt, Contra, freelancermap) quand c'est une vraie personne ou une mission, administration et finances (France Travail, URSSAF, imp\u00f4ts, banque, assurance), s\u00e9curit\u00e9 d'un compte, livraison ou rendez-vous \u00e0 venir.\nPAS IMPORTANT = newsletters, promotions, r\u00e9seaux sociaux, notifications automatiques sans action \u00e0 faire, re\u00e7us et confirmations sans suite.\n\nDans le doute, r\u00e9ponds important=true : rater un mail important co\u00fbte bien plus cher qu'une notification en trop.\nR\u00e9ponds UNIQUEMENT en JSON, raison écrite en français : {\"important\": true|false, \"reason\": \"15 mots maximum\"}" },
      { role: 'user', content: `De: ${from}\nObjet: ${subject}\n\n${text}` }
    ]
  } } };
});

const src = $('IA ?').all();
return $input.all().map((it, i) => {
  const { from, subject } = src[i].json;
  let important = true, reason = 'IA indisponible, à vérifier';
  try {
    const r = JSON.parse(it.json.choices[0].message.content);
    important = r.important !== false;
    reason = r.reason || '';
  } catch (e) {}
  return { json: { important, from, subject, reason, kind: 'ia', msg: `📬 ${subject}\nDe : ${from}\n→ ${reason}` } };
});

// ponytail: digest lives in workflow static data, capped at 500 entries; a DB table if it must survive n8n data loss
const sd = $getWorkflowStaticData('global');
const add = $input.all().map(({ json: i }) => ({ from: i.from, subject: i.subject, kind: i.kind || 'ia', reason: i.reason || '' }));
sd.ignored = (sd.ignored || []).concat(add).slice(-500);
return [];

const sd = $getWorkflowStaticData('global');
const list = sd.ignored || [];
if (!list.length) return [];
sd.ignored = [];
const news = {}, ai = [];
for (const i of list) {
  const name = (i.from.match(/^"?([^"<]+?)"?\s*</)?.[1] || i.from).trim();
  if (i.kind === 'newsletter') news[name] = (news[name] || 0) + 1;
  else ai.push(`• ${i.subject} — ${name}\n   ↳ ${i.reason}`);
}
const nl = Object.entries(news).sort((a, b) => b[1] - a[1]).map(([k, n]) => k + (n > 1 ? ' ×' + n : ''));
let text = `🗞️ Résumé du jour : ${list.length} mail(s) ignoré(s)\n`;
if (ai.length) text += `\n🤖 Jugés peu importants, à vérifier :\n${ai.join('\n')}\n`;
if (nl.length) text += `\n📰 Newsletters : ${nl.join(', ')}`;
if (text.length > 3900) text = text.slice(0, 3900) + '\n…(tronqué)';
return [{ json: { text } }];
